import 'react-native-url-polyfill/auto';
import React, { useEffect, useState } from 'react';
import { View, Text, ActivityIndicator, StyleSheet, Platform } from 'react-native';
import { StatusBar } from 'expo-status-bar';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import AsyncStorage from '@react-native-async-storage/async-storage';
import * as Device from 'expo-device';
import { AuthProvider } from './src/context/AuthContext';
import { ModeProvider } from './src/context/ModeContext';
import AppNavigator from './src/navigation/AppNavigator';
import InterestsScreen from './src/screens/onboarding/InterestsScreen';
import SuspendedScreen from './src/components/SuspendedScreen';
import { colors, spacing, theme } from './src/theme/colors';
import { supabase } from './src/lib/supabase';
import { getDeviceUserId } from './src/lib/deviceUser';
import { registerForPush } from './src/lib/push';
import { installAutoTranslate } from './src/lib/autoTranslate';
import { usePrefs } from './src/lib/prefs';

installAutoTranslate();

export default function AppMain() {
  const { lang } = usePrefs();
  const [checkingOnboarding, setCheckingOnboarding] = useState(true);
  const [onboardingDone, setOnboardingDone] = useState(false);
  const [banInfo, setBanInfo] = useState({ checked: false, banned: false, reason: '' });

  useEffect(() => {
    AsyncStorage.getItem('zuno_onboarding_done')
      .then((value) => {
        setOnboardingDone(value === 'true');
      })
      .catch((e) => {
        console.log('Erreur lecture onboarding, on continue quand même :', e.message);
        setOnboardingDone(false);
      })
      .finally(() => {
        setCheckingOnboarding(false);
      });
  }, []);

  useEffect(() => {
    if (checkingOnboarding || !onboardingDone) return;
    // Ne vérifie le bannissement que pour les personnes ayant déjà terminé
    // l'accueil (un tout nouveau venu n'a pas encore de compte à bloquer).
    registerForPush();

    getDeviceUserId()
      .then((myId) =>
        supabase.from('users').select('is_banned, ban_reason').eq('id', myId).maybeSingle()
      )
      .then(({ data }) => {
        setBanInfo({ checked: true, banned: data?.is_banned || false, reason: data?.ban_reason || '' });
      })
      .catch((e) => {
        console.log('Erreur vérification bannissement, on continue quand même :', e.message);
        setBanInfo({ checked: true, banned: false, reason: '' });
      });

    // Enregistre discrètement la dernière connexion (ville approximative
    // déduite de l'adresse IP, modèle d'appareil) — utile pour le
    // tableau de bord admin, sans jamais demander de permission à la
    // personne. Ne bloque jamais l'ouverture de l'appli si ça échoue.
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (!session) return;
      supabase.functions
        .invoke('track-session', {
          body: {
            deviceModel: Device.modelName,
            osName: Device.osName,
            osVersion: Device.osVersion,
          },
        })
        .catch((e) => console.log('Erreur enregistrement session (sans conséquence) :', e.message));
    });
  }, [checkingOnboarding, onboardingDone]);

  if (checkingOnboarding || (onboardingDone && !banInfo.checked)) {
    return (
      <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', backgroundColor: colors.purple }}>
        <ActivityIndicator color={colors.white} size="large" />
      </View>
    );
  }

  if (banInfo.banned) {
    // Revérifie le statut (par exemple après une réactivation depuis le tableau de bord).
    const recheckBan = async () => {
      try {
        const myId = await getDeviceUserId();
        const { data } = await supabase.from('users').select('is_banned, ban_reason').eq('id', myId).maybeSingle();
        setBanInfo({ checked: true, banned: data?.is_banned || false, reason: data?.ban_reason || '' });
      } catch (e) {
        console.log('Erreur revérification bannissement :', e.message);
      }
    };
    return (
      <SafeAreaProvider>
        <SuspendedScreen reason={banInfo.reason} onRetry={recheckBan} />
      </SafeAreaProvider>
    );
  }

  return (
    <SafeAreaProvider key={lang}>
      <AuthProvider>
        <ModeProvider>
          <StatusBar style="light" />
          {onboardingDone ? (
            <AppNavigator />
          ) : (
            <InterestsScreen onDone={() => setOnboardingDone(true)} />
          )}
        </ModeProvider>
      </AuthProvider>
    </SafeAreaProvider>
  );
}
